// Page motion: the findings strip under the hero, the pinned tour and a light reveal for sections.
// Every number shown comes from recorded real scanner output. Reduced motion gets final states.
const REDUCED = matchMedia('(prefers-reduced-motion: reduce)').matches;
const $ = s => document.querySelector(s);

// Findings and numbers come from web/demo_results.json: the recorded output of the real scanner on the bundled sample
// (regenerated by scripts/gen_demo_results.py). Nothing is typed in here.
let RESULTS = null;
try { const r = await fetch('/static/demo_results.json'); if (r.ok) RESULTS = await r.json(); } catch { /* handled below */ }
const VULN = RESULTS && RESULTS.samples && RESULTS.samples['vulnerable-python'];

/* ------------------------------------------------------------ findings strip: one tile per finding, grouped by file */
// Stays hidden when the recorded results are missing, rather than showing invented numbers.
{
  const fig = document.getElementById('strip'), b = VULN && VULN.before;
  if (fig && b && b.items && b.items.length) {
    const ORDER = ['critical', 'high', 'medium', 'low', 'informational'];
    const byFile = new Map();
    for (const i of b.items) { if (!byFile.has(i.path)) byFile.set(i.path, []); byFile.get(i.path).push(i); }
    const files = document.getElementById('strip-files');
    let n = 0;
    for (const [path, items] of byFile) {
      const row = document.createElement('div'); row.className = 'strip-row';
      const name = document.createElement('span'); name.className = 'mono strip-path'; name.textContent = path;
      const tiles = document.createElement('span'); tiles.className = 'strip-tiles';
      items.sort((x, y) => ORDER.indexOf(x.severity) - ORDER.indexOf(y.severity) || x.line - y.line).forEach(i => {
        const t = document.createElement('i');
        t.className = `tile ${i.severity}`; t.style.setProperty('--n', n++);
        t.title = `${i.severity} · ${i.rule} · ${path}:${i.line}`;
        tiles.appendChild(t);
      });
      row.append(name, tiles); files.appendChild(row);
    }
    const counts = ORDER.map(s => [s, b.items.filter(i => i.severity === s).length]).filter(([, c]) => c);
    document.getElementById('strip-legend').innerHTML = counts.map(([s, c]) => `<li><i class="tile ${s}"></i>${s} <b class="mono">${c}</b></li>`).join('');
    document.getElementById('strip-idx').textContent = Number(b.normalizedIndex).toFixed(1);
    fig.setAttribute('aria-label', `${b.findings} findings in ${b.filesScanned} files of sample_projects/vulnerable-python; security debt index ${Number(b.normalizedIndex).toFixed(1)} of 100`);
    fig.hidden = false;
    // the tiles land once, in order, the first time the strip is on screen
    if (!REDUCED) {
      fig.classList.add('pre');
      new IntersectionObserver(([e], io) => { if (e.isIntersecting) { fig.classList.remove('pre'); io.disconnect(); } }, { threshold: 0.4 }).observe(fig);
    }
  }
}

/* ------------------------------------------------------------ scan form: show the chosen archive */
{
  const input = document.getElementById('file'), t = document.getElementById('drop-t'), drop = input && input.closest('.drop');
  if (input && t) {
    input.addEventListener('change', () => { const f = input.files[0]; t.textContent = f ? `${f.name} · ${(f.size / 1024).toFixed(0)} KB` : 'Drop a .zip here or choose a file'; });
    ['dragenter', 'dragover'].forEach(e => drop.addEventListener(e, () => drop.classList.add('over')));
    ['dragleave', 'drop'].forEach(e => drop.addEventListener(e, () => drop.classList.remove('over')));
  }
}

/* ------------------------------------------------------------ Fig 2: the scan line sweeps the snippet each time its tour step opens */
// Without motion (or JS) the snippet shows its final state: the finding already highlighted and annotated.
const runFig2 = (() => {
  const code = document.getElementById('code');
  if (!code || REDUCED) return () => {};
  const ol = code.querySelector('ol'), lines = [...ol.querySelectorAll('li:not(.ann)')];
  const target = ol.querySelector('li.target'), ann = document.getElementById('annot'), pEl = document.getElementById('scrub-p');
  const beam = document.createElement('div'); beam.className = 'scrub-beam'; beam.setAttribute('aria-hidden', 'true');
  code.classList.add('scrub'); code.appendChild(beam);
  const render = p => {
    const y = ol.offsetTop + p * ol.offsetHeight;                   // beam position inside the panel
    beam.style.transform = `translateY(${y}px)`;
    lines.forEach(li => li.classList.toggle('seen', li.offsetTop + li.offsetHeight / 2 <= y));
    const hit = target.classList.contains('seen');
    target.classList.toggle('hit', hit); ann.classList.toggle('open', hit);
    pEl.textContent = p >= 1 ? 'scan complete · 1 finding' : `scan ${Math.round(p * 100)}%`;
  };
  render(0);
  let raf = 0;
  return () => {
    cancelAnimationFrame(raf);
    const t0 = performance.now(), DUR = 1800;
    const tick = now => { const p = Math.min(1, (now - t0) / DUR); render(p); if (p < 1) raf = requestAnimationFrame(tick); };
    raf = requestAnimationFrame(tick);
  };
})();

/* ------------------------------------------------------------ tour: one pinned panel whose scene follows the scroll */
// Wide screens: the track is taller than the viewport and the panel is sticky, so scrolling through the track
// changes the scene rather than moving the page on. Narrow screens: the steps are tabs and a tap swaps the scene.
const story = (() => {
  const root = document.getElementById('story'), track = document.getElementById('story-track');
  if (!root || !track) return null;
  const steps = [...root.querySelectorAll('.step')], scenes = [...root.querySelectorAll('.scene')], nEl = document.getElementById('story-n');
  const N = scenes.length, PIN_TOP = 60, screen = root.querySelector('.screen');
  const pinned = () => matchMedia('(min-width: 901px)').matches;
  root.classList.add('js-story');
  // progress rail: the coloured fill runs from the first dot to `pos`, a fractional step index, so while scrolling
  // it travels between dots and reaches the next one exactly as that step opens
  const list = root.querySelector('.steps'), DOT_C = 27;            // dot centre inside a step (site.css .step::before)
  let pos = 0;
  const rail = () => {
    const c = steps.map(s => s.offsetTop + DOT_C), k = Math.min(N - 2, Math.floor(pos)), f = pos - k;
    list.style.setProperty('--rail-h', `${c[N - 1] - c[0]}px`);
    list.style.setProperty('--fill', `${c[k] + (c[k + 1] - c[k]) * f - c[0]}px`);
  };
  list.addEventListener('transitionend', e => { if (e.propertyName === 'max-height') rail(); }); // step text opening moves the dots
  let cur = -1;
  const show = i => {
    if (i === cur) return;
    cur = i;
    steps.forEach((s, k) => { s.classList.toggle('on', k === i); s.classList.toggle('done', k < i); s.querySelector('button').setAttribute('aria-current', k === i ? 'step' : 'false'); });
    if (!pinned()) {                                                 // tab strip: keep the active tab in view
      pos = i; rail();
      list.scrollTo({ left: steps[i].offsetLeft - 16, behavior: REDUCED ? 'auto' : 'smooth' });
    }
    scenes.forEach((s, k) => { s.classList.toggle('on', k === i); s.inert = k !== i; });
    nEl.textContent = `step ${i + 1} of ${N}`;
    screen.style.setProperty('--sc', getComputedStyle(steps[i]).getPropertyValue('--c'));  // the panel wears the open step's colour
    if (i === 4) runFig2();
    root.dispatchEvent(new CustomEvent('scene', { detail: i }));
  };
  // the scroll distance through the track is split into N equal slices, one per scene
  const span = () => track.offsetHeight - (innerHeight - PIN_TOP);
  const fromScroll = () => {
    if (!pinned()) return;
    const p = (PIN_TOP - track.getBoundingClientRect().top) / Math.max(1, span());
    pos = Math.min(N - 1, Math.max(0, p * N));
    show(Math.min(N - 1, Math.floor(pos)));
    rail();
  };
  const goTo = i => {
    if (!pinned()) { show(i); root.scrollIntoView({ behavior: REDUCED ? 'auto' : 'smooth' }); return; }
    const top = scrollY + track.getBoundingClientRect().top - PIN_TOP + span() * (i + 0.5) / N;
    scrollTo({ top, behavior: REDUCED ? 'auto' : 'smooth' });
  };
  steps.forEach((s, i) => s.querySelector('button').addEventListener('click', () => (pinned() ? goTo(i) : show(i))));
  // arrow keys move between steps, like a tab list
  root.querySelector('.steps').addEventListener('keydown', e => {
    const d = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[e.key];
    if (!d) return;
    e.preventDefault();
    const i = Math.min(N - 1, Math.max(0, cur + d));
    steps[i].querySelector('button').focus(); (pinned() ? goTo(i) : show(i));
  });
  addEventListener('scroll', fromScroll, { passive: true });         // one rect read per event; show() is a no-op unless the scene changes
  addEventListener('resize', () => { fromScroll(); rail(); });
  show(0); fromScroll(); rail();
  return { root, goTo, current: () => cur };
})();

// any link carrying data-scene (nav, hero button) opens that step of the tour
document.querySelectorAll('a[data-scene]').forEach(a => a.addEventListener('click', e => {
  if (!story) return;
  e.preventDefault(); story.goTo(Number(a.dataset.scene));
}));


/* ------------------------------------------------------------ Fig 3: before / after from the recorded real scans */
{
  const t = document.getElementById('fig3-body');
  const n = document.getElementById('fig3-note');
  if (t && VULN && VULN.before && VULN.after) {
    const b = VULN.before, a = VULN.after, f = (v, d = 1) => (v == null ? 'n/a' : Number(v).toFixed(d));
    const row = (l, x) => `<tr><td>${l}</td><td class="mono ${x.normalizedIndex > 60 ? 'crit' : ''}">${f(x.normalizedIndex)}</td><td class="mono">${x.findings}</td><td class="mono">${f(x.rawUnits, 2)}</td><td>${x.decision.replace(/_/g, ' ')}*</td></tr>`;
    t.innerHTML = row('as shipped', b) + row(`after ${a.fixesApplied} fixes`, a)
      + `<tr class="delta"><td>change</td><td class="mono up"><span class="circled">${f(a.normalizedIndex - b.normalizedIndex)}</span></td><td class="mono up">${a.findings - b.findings}</td><td class="mono up">${f(a.rawUnits - b.rawUnits, 2)}</td><td></td></tr>`;
    if (n) n.textContent = `fixed ${b.findings} of ${b.findings} detected findings → the index went down. zero findings is not proof the code is secure!`;
  } else if (t) {
    t.innerHTML = '<tr><td colspan="5">Recorded results unavailable.</td></tr>'; // never leave "Loading…" frozen when the data simply didn't arrive
    if (n) n.textContent = 'recorded results unavailable';
  }
}


/* ------------------------------------------------------------ navigation: solid bar once scrolled, hide on fast scroll down, scroll-spy */
{
  const nav = $('#nav'), links = $('#nav-links'), ind = $('#nav-ind'), burger = $('#burger');
  const anchors = [...links.querySelectorAll('a')];
  // #app has no nav link of its own: reaching it clears the highlight instead of leaving the previous section lit
  const sections = [...new Set([...anchors.map((a) => a.getAttribute('href')), '#app'])].map((h) => document.querySelector(h)).filter(Boolean)
    .sort((a, b) => (a.compareDocumentPosition(b) & Node.DOCUMENT_POSITION_FOLLOWING ? -1 : 1));
  let current = null;
  const moveInd = (a) => {
    if (!a) { ind.style.opacity = '0'; return; }
    ind.style.opacity = '1'; ind.style.width = `${a.offsetWidth}px`; ind.style.transform = `translateX(${a.offsetLeft}px)`;
  };
  // three links share #story; inside it, the lit one is the last whose data-scene is at or before the open step
  const storyLink = () => {
    const at = story ? story.current() : 0;
    return anchors.filter((a) => a.dataset.scene != null && Number(a.dataset.scene) <= at).pop();
  };
  const setActive = (id) => {
    const key = id === 'story' ? `story:${story ? story.current() : 0}` : id;
    if (key === current) return;
    current = key;
    const on = id === 'story' ? storyLink() : anchors.find((a) => a.getAttribute('href') === `#${id}`);
    anchors.forEach((a) => a.classList.toggle('on', a === on));
    moveInd(on);
  };
  if (story) story.root.addEventListener('scene', () => onScroll());
  anchors.forEach((a) => {
    a.addEventListener('mouseenter', () => moveInd(a));
    a.addEventListener('click', () => { links.classList.remove('open'); burger.setAttribute('aria-expanded', 'false'); });
  });
  links.addEventListener('mouseleave', () => moveInd(anchors.find((a) => a.classList.contains('on'))));
  burger.addEventListener('click', () => {
    const open = !links.classList.contains('open');
    links.classList.toggle('open', open); burger.setAttribute('aria-expanded', String(open));
    burger.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
  });
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && links.classList.contains('open')) { burger.click(); burger.focus(); } });

  let lastY = scrollY, ticking = false;
  const onScroll = () => {
    ticking = false;
    const y = scrollY;
    nav.classList.toggle('scrolled', y > 10);
    nav.classList.toggle('hide', y > 600 && y - lastY > 12 && !links.classList.contains('open'));
    if (y < lastY) nav.classList.remove('hide');
    lastY = y;
    // the active section is the last one whose top has passed a line 35% down the viewport
    let id = null;
    for (const s of sections) if (s.getBoundingClientRect().top < innerHeight * 0.35) id = s.id;
    setActive(id);
  };
  addEventListener('scroll', () => { if (!ticking) { ticking = true; requestAnimationFrame(onScroll); } }, { passive: true });
  addEventListener('resize', () => moveInd(anchors.find((a) => a.classList.contains('on'))));
  onScroll();
}

/* ------------------------------------------------------------ scroll reveals */
{
  const io = new IntersectionObserver((entries) => {
    for (const e of entries) if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); }
  }, { rootMargin: '0px 0px -10% 0px', threshold: 0.05 });
  document.querySelectorAll('.rv').forEach((el) => io.observe(el));
}

/* ------------------------------------------------------------ FAQ: animate open/close height, one open at a time */
{
  const items = [...document.querySelectorAll('.faq details')];
  const animate = (d, open) => {
    const body = d.querySelector('.faq-a');
    if (REDUCED || !body.animate) { d.open = open; return; }
    if (open) {
      d.open = true;
      body.animate([{ height: '0px', opacity: 0 }, { height: `${body.scrollHeight}px`, opacity: 1 }], { duration: 380, easing: 'cubic-bezier(.22,1,.36,1)' });
    } else {
      const a = body.animate([{ height: `${body.offsetHeight}px`, opacity: 1 }, { height: '0px', opacity: 0 }], { duration: 280, easing: 'cubic-bezier(.22,1,.36,1)' });
      a.onfinish = () => { d.open = false; };
    }
  };
  items.forEach((d) => d.querySelector('summary').addEventListener('click', (e) => {
    e.preventDefault();
    const open = !d.open;
    if (open) items.filter((x) => x !== d && x.open).forEach((x) => animate(x, false));
    animate(d, open);
  }));
}
